using Godot;
using System;
using GArray=Godot.Collections.Array;

public partial class TransformationExamples : RefCounted
{
    private static Resource New(string name)=>GD.Load<GDScript>("res://Workspaces/TransformationWorkspace/transformation_"+name+".gd").New().As<Resource>();
    private static GodotObject Art(Resource state)=>state.Get("artwork").AsGodotObject();
    public Image image(string kind,double amount)
    {
        var result=Image.CreateEmpty(160,120,false,Image.Format.Rgba8);result.Fill(new Color(0,0,0,0));for(int y=0;y<120;y++)for(int x=0;x<160;x++){var point=new Vector2(x+.5f,y+.5f);var center=new Vector2(80,60);var color=new Color(0,0,0,0);if(kind=="eye"){var q=(point-center)/new Vector2(61,(float)Math.Max(3,32*amount));if(q.LengthSquared()<1){color=new Color(q.Length()>.88f?"132433":"fcf9e9");if(point.DistanceTo(center)<12*amount)color=new Color("54babc");if(point.DistanceTo(center)<5*amount)color=new Color("132433");}}else if(kind=="mouth"){var q=(point-center)/new Vector2((float)(45+15*amount),(float)Math.Max(3,40*amount));if(q.LengthSquared()<1){color=new Color(q.Length()>.84f?"c23851":"381a34");if(q.Y<-.15&&Math.Abs(q.X)<.7&&amount>.2)color=new Color("fff3db");if(((point-new Vector2(80,77))/new Vector2(29,13)).LengthSquared()<1&&amount>.2)color=new Color("ef718b");}}else if(kind=="ball"){float distance=point.DistanceTo(center);if(distance<43)color=new Color(distance>39?"d8773f":"ffc977");if(point.DistanceTo(new Vector2(65,46))<10)color=new Color("ffefb6");}else if(kind=="blood"){var q=(point-new Vector2(80,(float)(20+30*amount)))/new Vector2((float)(22-9*amount),(float)(15+40*amount));if(q.LengthSquared()<1)color=new Color(q.Length()>.8f?"a41f49":"e34557");}else if(kind=="cut"){var q=(point-center)/new Vector2(64,(float)Math.Max(2,18*amount));if(q.LengthSquared()<1)color=new Color(q.Length()>.75f?"aa2847":"411b39");}else if(kind=="brow"&&Math.Abs(point.Y-(55+Math.Pow((point.X-80)/55,2)*12))<5&&Math.Abs(point.X-80)<58)color=new Color("5b3f48");result.SetPixel(x,y,color);}return result;
    }
    public Resource component(Resource document,string title,Vector2 position,Vector2 dimensions){using var resources=new TransformationResourceOperations();var item=resources.make_component(new Vector2I(160,120),title);item.Set("base_size",dimensions);var art=Art(item.Get("states").AsGodotArray()[0].As<Resource>());art.Set("position",position);art.Set("dimensions",dimensions);document.Get("components").AsGodotArray().Add(item);return item;}
    public Resource state(Resource item,string title,Image bitmap){using var resources=new TransformationResourceOperations();var result=resources.copy_state(item.Get("states").AsGodotArray()[0].As<Resource>(),true);result.Set("title",title);var texture=ImageTexture.CreateFromImage(bitmap);Art(result).Set("texture",texture);Art(result).Set("paint_base",texture);item.Get("states").AsGodotArray().Add(result);return result;}
    public Resource key(Resource item,double at,Resource state,string mode){var result=New("key");result.Set("id",ActorData.new_id());result.Set("time",at);result.Set("state_id",state.Get("id"));result.Set("mode",mode);item.Get("keys").AsGodotArray().Add(result);return result;}
    public void finish(Resource item,GArray states){var target=item.Get("states").AsGodotArray();target.Clear();foreach(var state in states)target.Add(state);item.Set("default_state_id",states[0].AsGodotObject().Get("id"));}
    public Resource create(string title)
    {
        var document=New("document");document.Set("canvas_size",new Vector2I(640,400));document.Set("duration",3.0);document.Get("metadata").AsGodotDictionary()["example"]=title;using var resources=new TransformationResourceOperations();Resource Painted(Resource item,string label,string kind,double amount=1){using var bitmap=image(kind,amount);return state(item,label,bitmap);}Resource Empty(Resource item,string label){using var bitmap=Image.CreateEmpty(160,120,false,Image.Format.Rgba8);return state(item,label,bitmap);}void States(Resource item,params Resource[] states){var values=new GArray();foreach(var state in states)values.Add(state);finish(item,values);}void Key(Resource item,double at,Resource state,string mode="Smooth morph")=>key(item,at,state,mode);
        if(title=="Bleeding cut")
        {
            var cut=component(document,"Cut",new Vector2(170,45),new Vector2(300,100));var closed=Painted(cut,"Closed","cut",.05);var open=Painted(cut,"Open","cut");States(cut,closed,open);Key(cut,0,closed);Key(cut,.5,open);Key(cut,3,open);var blood=component(document,"Blood",new Vector2(240,75),new Vector2(160,240));var empty=Empty(blood,"Empty");var gathering=Painted(blood,"Gathering","blood",0);var stream=Painted(blood,"Stream","blood");foreach(var state in new[]{empty,gathering,stream})state.Set("pivot",new Vector2(.5f,.1f));States(blood,empty,gathering,stream);Key(blood,0,empty);var reveal=key(blood,.7,gathering,"Reveal");reveal.Set("reveal_path",new[]{new Vector2(.5f,.1f),new Vector2(.5f,.95f)});reveal.Set("reveal_width",.35);Key(blood,1.7,stream);Key(blood,3,stream);var drop=component(document,"Blood drop",new Vector2(295,210),new Vector2(50,70));var hidden=Empty(drop,"Hidden");var formed=Painted(drop,"Formed","blood",.7);var falling=resources.copy_state(formed,true);falling.Set("title","Falling");Art(falling).Set("position",Art(falling).Get("position").AsVector2()+new Vector2(0,110));Art(falling).Set("opacity",0.0);States(drop,hidden,formed,falling);Key(drop,0,hidden);Key(drop,1.4,hidden);Key(drop,1.7,formed);Key(drop,2.8,falling);Key(drop,3,hidden,"Step");
        }
        else if(title=="Bouncing ball")
        {
            var ball=component(document,"Ball",new Vector2(230,40),new Vector2(180,180));var top=Painted(ball,"Airborne","ball");var floor=resources.copy_state(top,true);floor.Set("title","Squash");Art(floor).Set("position",new Vector2(205,265));Art(floor).Set("dimensions",new Vector2(230,100));floor.Set("pivot",new Vector2(.5f,1));var stretch=resources.copy_state(top,true);stretch.Set("title","Stretch");Art(stretch).Set("position",new Vector2(250,150));Art(stretch).Set("dimensions",new Vector2(140,210));States(ball,top,floor,stretch);Key(ball,0,top);Key(ball,1,floor);Key(ball,1.3,stretch);Key(ball,2,top);Key(ball,3,top);
        }
        else
        {
            if(title=="Layered face"){var face=component(document,"Face",new Vector2(90,5),new Vector2(460,380));States(face,Painted(face,"Base","ball"));}if(title is "Blinking eye" or "Layered face")for(int index=0;index<(title=="Layered face"?2:1);index++){var eye=component(document,"Eye "+(index+1),title=="Layered face"?new Vector2(145+index*180,90):new Vector2(170,110),title=="Layered face"?new Vector2(170,100):new Vector2(300,180));var open=Painted(eye,"Open","eye");var closed=Painted(eye,"Closed","eye",.08);States(eye,open,closed);Key(eye,0,open);Key(eye,.75+index*.2,open);Key(eye,1+index*.2,closed);Key(eye,1.25+index*.2,open);Key(eye,3,open);}if(title is "Talking mouth" or "Layered face"){var mouth=component(document,"Mouth",title=="Layered face"?new Vector2(230,210):new Vector2(170,90),title=="Layered face"?new Vector2(180,120):new Vector2(300,220));var states=new[]{Painted(mouth,"Closed","mouth",.06),Painted(mouth,"Open","mouth"),Painted(mouth,"Smile","mouth",.3),Painted(mouth,"O shape","mouth",.65)};States(mouth,states);for(int index=0;index<5;index++)Key(mouth,index*.6,states[index%4]);}if(title=="Layered face")for(int index=0;index<2;index++){var brow=component(document,"Brow "+(index+1),new Vector2(145+index*180,50),new Vector2(170,70));var neutral=Painted(brow,"Neutral","brow");var raised=resources.copy_state(neutral,true);raised.Set("title","Raised");Art(raised).Set("position",Art(raised).Get("position").AsVector2()-new Vector2(0,25));Art(raised).Set("rotation",index==0?-.12:.12);States(brow,neutral,raised);Key(brow,0,neutral);Key(brow,1.5,raised);Key(brow,3,neutral);}
        }return document;
    }
}
